from dataclasses import dataclass

@dataclass
class Lease:
    owner: str
    epoch: int
    expires_at: int

class LeaseManager:
    def __init__(self, ttl):
        self.ttl = ttl
        self.leases = {}

    def acquire(self, key, owner, now):
        current = self.leases.get(key)
        if current is None or current.expires_at <= now:
            epoch = 1 if current is None else current.epoch + 1
            lease = Lease(owner, epoch, now + self.ttl)
            self.leases[key] = lease
            return lease
        return None

    def valid(self, key, owner, epoch, now):
        lease = self.leases.get(key)
        return lease is not None and lease.owner == owner and lease.epoch == epoch and lease.expires_at > now

class VersionedCache:
    def __init__(self, lease_manager, version_store, quorum, invalidator):
        self.lease_manager = lease_manager
        self.version_store = version_store
        self.quorum = quorum
        self.invalidator = invalidator
        self.entries = {}

    def read(self, key, owner, now, min_version=0):
        entry = self.entries.get(key)
        if entry and self.lease_manager.valid(key, owner, entry.epoch, now) and entry.version >= min_version:
            return entry
        return None

    def write(self, key, value, owner, expected_version, now):
        lease = self.lease_manager.leases.get(key)
        if lease is None or not self.lease_manager.valid(key, owner, lease.epoch, now):
            return False
        current = self.version_store.read(key)
        if current != expected_version:
            return False
        new_version = current + 1
        if not self.quorum.commit(key, value, new_version, lease.epoch):
            return False
        self.version_store.cas(key, expected_version, new_version)
        self.entries[key] = Entry(value, new_version, lease.epoch)
        self.invalidator.publish(key, new_version)
        return True
